  last_correct_at INTEGER,
  redo_due_at     INTEGER,
  redo_guaranteed INTEGER NOT NULL DEFAULT 0 CHECK (redo_guaranteed IN (0, 1)),
  updated_at      INTEGER NOT NULL
) STRICT;
